module bolt_packer (input clk, input rst_n, input start, input [9:0] B, input [3:0] num_companies, input [3:0] company_index, input [3:0] num_packs, input [9:0] pack_size, input config_valid, output reg [9:0] min_advertised, output reg found, output reg impossible, output reg done); reg [2:0] state; reg [3:0] current_company; reg [9:0] company_packs [10][10]; reg [9:0] real_amounts [10][10]; reg [9:0] current_B; always_ff @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'd0; current_company <= 0; end else begin case (state) 3'd0: if (start) state <= 3'd1; else state <= 3'd0; break; 3'd1: if (config_valid) begin company_packs[current_company][0] <= pack_size; current_company <= current_company + 1; if (current_company == num_companies) state <= 3'd2; end break; 3'd2: state <= 3'd3; break; 3'd3: state <= 3'd4; break; 3'd4: if (start || rst_n) state <= 3'd0; break; endcase end end end always_comb begin case (state) 3'd4: min_advertised <= 10'd0; found <= 1'b0; impossible <= 1'b1; done <= 1'b1; default: done <= 1'b0; endcase end endmodule